"""The season the planner reads: typed, immutable, and only the columns the planner uses."""

from __future__ import annotations

from dataclasses import dataclass

WEEKS_PER_MONTH = 4
DEFER_WEEKS = 26        # an untrimmed circuit waits this many weeks past the season for the next one

Weeks = tuple[tuple[int, int], ...]     # spans of weeks, each (first, last), both included


@dataclass(frozen=True)
class Circuit:
    cid: str
    region: str
    miles: int
    cost: int           # $k to trim the circuit
    risk: int           # $k a year of tree-caused outage risk that a trim removes
    weeks: int          # crew-weeks of work to trim it
    growth: float       # $k a week by which the weekly risk grows while the circuit waits
    windows: Weeks      # the trim must lie inside one of these; () means the whole season
    must: bool          # compliance: it must be trimmed this season

    def carried(self, end: int) -> int:
        """$k of risk carried from week 0 until a trim that ends at `end` (weeks 0 to end - 1)."""
        weekly = self.risk / 52
        return round(weekly * end + self.growth * end * (end - 1) / 2)


@dataclass(frozen=True)
class Season:
    name: str
    budget: int         # $k for the year's trimming
    crews: int          # crews working the season
    months: int         # months in the season, each WEEKS_PER_MONTH weeks
    crew_off: dict[str, Weeks]      # crew id -> weeks it cannot work
    circuits: tuple[Circuit, ...]

    def circuit(self, cid: str) -> Circuit:
        return next(c for c in self.circuits if c.cid == cid)


@dataclass(frozen=True)
class Override:
    """Stub for lesson 14.1.6: a planner's decision the plan must keep."""
    kind: str                       # "pin", "skip" or "force"
    cid: str
    crew: str | None = None
    start: int | None = None
    reason: str = ""


def spans(raw: list) -> Weeks:
    return tuple((int(first), int(last)) for first, last in raw)


def season_from_dict(raw: dict) -> Season:
    """Read the columns the planner uses. Columns it does not use yet are ignored.

    A circuit with no windows may be trimmed in any week, one with no must flag is optional work,
    and a season with no crew_off has every crew at work every week.
    """
    circuits = tuple(Circuit(c["id"], c["region"], int(c["miles"]), int(c["cost"]), int(c["risk"]),
                             int(c["weeks"]), float(c["growth"]), spans(c.get("windows") or []),
                             bool(c.get("must", False)))
                     for c in raw["circuits"])
    crew_off = {k: spans(weeks) for k, weeks in (raw.get("crew_off") or {}).items()}
    return Season(raw.get("name", "season"), int(raw["budget"]), int(raw["crews"]), int(raw["months"]),
                  crew_off, circuits)

"""A seeded generator of fictional trimming seasons, in the shape the circuit inventory exports.

Each column is drawn from its own random stream, named after the seed, the size and the column, so
adding a column later never changes the values of the columns already there.
"""

from __future__ import annotations

import math
import random

SIZES = {"tiny": 6, "small": 20, "medium": 60}
CREWS = {"tiny": 1, "small": 2, "medium": 6}
MONTHS = 6                                                     # April to September
REGIONS = ("North", "River", "Hills")


def stream(seed: int, size: str, column: str) -> random.Random:
    return random.Random(f"{seed}-{size}-{column}")


def scenario(size: str = "small", seed: int = 54) -> dict:
    """One season: a budget and the circuits, as plain JSON-ready values."""
    n = SIZES[size]
    draw = stream(seed, size, "circuits")
    circuits = []
    for i in range(1, n + 1):
        miles = draw.randint(8, 40)
        circuits.append({
            "id": f"C{i:02d}",
            "region": draw.choice(REGIONS),
            "miles": miles,
            "cost": round(miles * draw.uniform(3.0, 6.0)),       # $k to trim the whole circuit
            "risk": round(miles * draw.uniform(2.0, 12.0)),      # $k a year of tree-caused outage risk
        })
    work = stream(seed, size, "weeks")
    for c in circuits:
        c["weeks"] = math.ceil(c["miles"] / work.uniform(4.0, 7.0))     # crew-weeks to trim it
    growth = stream(seed, size, "growth")
    for c in circuits:
        c["growth"] = round(c["risk"] / 52 * growth.uniform(0.02, 0.10), 2)   # $k a week, every week
    access = stream(seed, size, "access")
    last = MONTHS * 4 - 1
    for c in circuits:
        c["must"] = access.random() < 0.15                     # overdue on its cycle: trim it this season
        if c["region"] == "River":
            c["windows"] = [[8, last]]                         # wet ground: no equipment before week 8
        elif c["region"] == "Hills" and access.random() < 0.5:
            c["windows"] = [[0, 5], [14, last]]                # nesting season closes weeks 6 to 13
        else:
            c["windows"] = []                                  # the whole season
    crew_off = {"K1": [[10, 11]]}                              # training
    if CREWS[size] > 1:
        crew_off[f"K{CREWS[size]}"] = [[14, 17]]               # held back for storm duty
    budget = round(0.45 * sum(c["cost"] for c in circuits))
    return {"name": f"{size}-{seed}", "budget": budget, "crews": CREWS[size], "months": MONTHS,
            "crew_off": crew_off, "circuits": circuits}

